#include <iostream>
#include <utility>
#include <vector>
using namespace std;

static pair<int, long long> far(const vector<vector<pair<int, long long>>>& adj, int src) {
    vector<long long> dist(adj.size(), -1);
    dist[src] = 0;
    vector<int> stack{src};
    int best = src;
    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        if (dist[u] > dist[best]) best = u;
        for (auto [v, w] : adj[u])
            if (dist[v] < 0) {
                dist[v] = dist[u] + w;
                stack.push_back(v);
            }
    }
    return {best, dist[best]};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<pair<int, long long>>> adj(n + 1);
    for (int j = 0; j < n - 1; j++) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    int a = far(adj, 1).first;
    cout << far(adj, a).second << '\n';
    return 0;
}

